'use strict';
const fs=require('fs');
const C={base:'app01sBuNbRyjVt47',table:'tbl3ZPAJF3FvbR90p',id:'AIR-SENTINEL-001',task:'sentinel-real-first-nws',attempt:'AIR-SENTINEL-001-DISPATCH-1',claimed:'Cybertron READY Sentinel Dispatcher v0.1',
 payload:'Reuse verified Sentinel V0.2.1 and existing Factory #95 precision candidate e4e6bf8197f177861e1fb9e6378a2a8e7bb85c7b. Correct the live-proven NWS point precision redirect with four-decimal official geometry coordinates; default Explore to official NWS coverage; explicitly label Demo / Samples. Preserve mobile styling, Home, Event Sheet, Explain This, saved area, same-origin /api/nws and api.weather.gov-only egress. NOAA/NWS only; no paid APIs, geolocation, notifications, unrelated architecture, product merge or production deployment. Factory branch/PR, tests, browser and live NWS evidence required.',
 next:'Factory consumes AIR-SENTINEL-001, builds isolated branch and product PR, verifies accepted mobile/NWS experience and persists durable Result + Receipt. Product merge and production deployment remain human-gated.',
 fields:{id:'fldn5b6yeYYRMPSaM',status:'fldgOSvL9pxpNRL2I',task:'fldHLUnihNBexSkZn',payload:'fldlnFmNjotAB08qm',attempt:'fldyMDCSTEW46XKZV',claimed:'fldjB7m1c9jaMhNKR',receipt:'fldO9RGHuCX7Bv0q0',result:'flde4kea7ckvPVn2g',next:'fldTpHDML0gVrtGk5'}};
function validate(f){const get=k=>f[C.fields[k]]??'';
 for(const k of ['id','task','payload','next'])if(get(k)!==C[k])throw Error(k.toUpperCase()+'_MISMATCH');
 if(get('status')==='COMPLETE'&&get('attempt')===C.attempt&&get('claimed')===C.claimed){const r=JSON.parse(get('receipt'));if(r.status!=='COMPLETE'||r.attempt!==C.attempt||r.production_write!==false||r.deploy!==false||!get('result').startsWith('https://github.com/VeritasDesign/free-frequency-genie-lab/pull/'))throw Error('TERMINAL_EVIDENCE_MISSING');return 'REPLAY'}
 if(get('status')==='CLAIMED'&&get('attempt')===C.attempt&&get('claimed')===C.claimed)return 'RESUME';
 if(get('status')!=='READY'||get('attempt')||get('claimed')||get('result')||get('receipt'))throw Error('FOREIGN_OR_INVALID_CLAIM');return 'APPLY';}
async function req(method,suffix='',body){const token=process.env.AIRTABLE_TOKEN;if(!token)throw Error('AIRTABLE_TOKEN_REQUIRED');const res=await fetch(`https://api.airtable.com/v0/${C.base}/${C.table}${suffix}`,{method,headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'},body:body&&JSON.stringify(body)});if(!res.ok)throw Error('AIRTABLE_HTTP_'+res.status);return res.json()}
async function locate(){const q=new URLSearchParams({returnFieldsByFieldId:'true',filterByFormula:`{Work Order ID}='${C.id}'`});const r=await req('GET','?'+q);if(r.records.length>1)throw Error('DUPLICATE_WORK_ORDER');return r.records[0]}
async function read(id){return req('GET','/'+id+'?returnFieldsByFieldId=true')}
async function patch(id,fields){return req('PATCH','/'+id+'?returnFieldsByFieldId=true',{fields})}
async function claim(){let r=await locate();if(!r){const fields={};for(const [k,v]of Object.entries({id:C.id,status:'READY',task:C.task,payload:C.payload,next:C.next}))fields[C.fields[k]]=v;const made=await req('POST','?returnFieldsByFieldId=true',{records:[{fields}]});r=await read(made.records[0].id);validate(r.fields);console.log('SEEDED_VERIFIED_READY '+r.id)}const d=validate(r.fields);if(d==='APPLY'){await patch(r.id,{[C.fields.status]:'CLAIMED',[C.fields.attempt]:C.attempt,[C.fields.claimed]:C.claimed});const check=await read(r.id);if(validate(check.fields)!=='RESUME')throw Error('CLAIM_READBACK_FAILED')}
 fs.mkdirSync('evidence',{recursive:true});fs.writeFileSync('evidence/control-state.json',JSON.stringify({record:r.id,decision:d,attempt:C.attempt}));if(process.env.GITHUB_OUTPUT)fs.appendFileSync(process.env.GITHUB_OUTPUT,`decision=${d}\nrecord=${r.id}\n`);console.log('FACTORY_DISPATCH '+d+' '+r.id);}
async function complete(){const r=await locate();if(!r||validate(r.fields)!=='RESUME')throw Error('RESUME_REQUIRED');const receipt=JSON.parse(fs.readFileSync('evidence/result.json'));if(receipt.attempt!==C.attempt||receipt.status!=='COMPLETE'||receipt.production_write!==false||receipt.deploy!==false)throw Error('INVALID_RECEIPT');await patch(r.id,{[C.fields.status]:'COMPLETE',[C.fields.result]:receipt.pr_url,[C.fields.receipt]:JSON.stringify(receipt)});const after=await read(r.id);if(validate(after.fields)!=='REPLAY'||after.fields[C.fields.result]!==receipt.pr_url||after.fields[C.fields.receipt]!==JSON.stringify(receipt))throw Error('COMPLETION_READBACK_FAILED');fs.writeFileSync('evidence/airtable-independent-readback.json',JSON.stringify(after,null,2));console.log('VERIFIED_DURABLE_COMPLETE '+r.id)}
module.exports={C,validate,req,locate,read,patch};if(require.main===module)(process.argv[2]==='complete'?complete():claim()).catch(e=>{console.error(e.message);process.exit(1)});
